;(function () {
  'use strict'

  document.addEventListener('DOMContentLoaded', initFormValidation)

  function injectErrorStyles() {
    const css = `
      .form-control-invalid-text { display: none !important; color: #d73a49; }
      .mb-4.invalid .form-control-invalid-text { display: block !important; }
      .mb-4.invalid .form-control { border-color: #d73a49 !important; }
      .mb-4.valid   .form-control { border-color: initial !important; }
    `
    const style = document.createElement('style')
    style.innerHTML = css
    document.head.appendChild(style)
  }

  function initFormValidation() {
    injectErrorStyles()

    const form = document.getElementById('eloquaForm')
    if (!form) return

    for (const w of form.querySelectorAll('.mb-4.invalid, .mb-4.valid')) {
      w.classList.remove('invalid', 'valid')
    }
    for (const el of form.querySelectorAll('.form-control-invalid-text')) {
      el.style.setProperty('display', 'none', 'important')
    }

    for (const field of form.querySelectorAll('input, select, textarea')) {
      field.addEventListener('input', () => validateField(field))
      field.addEventListener('change', () => validateField(field))
    }

    form.addEventListener('submit', onSubmit)
  }

  function validateField(field) {
    const wrapper = field.closest('.mb-4')
    if (!wrapper) return field.checkValidity()
    const err = wrapper.querySelector('.form-control-invalid-text')

    if (field.checkValidity()) {
      wrapper.classList.remove('invalid')
      wrapper.classList.add('valid')
      if (err) err.style.setProperty('display', 'none', 'important')
      return true
    } else {
      wrapper.classList.add('invalid')
      wrapper.classList.remove('valid')
      if (err) err.style.setProperty('display', 'block', 'important')
      return false
    }
  }

  function onSubmit(event) {
    const form = event.target
    let ok = true

    for (const f of form.querySelectorAll('input, select, textarea')) {
      if (!validateField(f)) ok = false
    }

    if (!ok) {
      event.preventDefault()
      event.stopPropagation()
    }

    form.classList.add('validated')
  }
})()
