document.addEventListener('DOMContentLoaded', initForm)

function initForm() {
  const params = new URLSearchParams(window.location.search)
  for (const [key, value] of params.entries()) {
    if (key === 'partnershipType') {
      for (const rb of document.querySelectorAll(`input[name="${key}"]`)) {
        if (rb.value === value) rb.checked = true
      }
    } else {
      const field = document.querySelector(`input[name="${key}"], select[name="${key}"], textarea[name="${key}"]`)
      if (field) field.value = value
    }
  }

  const partnershipElements = document.querySelectorAll('.js-partnership-channels, .js-partnership-technology')
  for (const el of partnershipElements) {
    el.addEventListener('change', updateFields)
  }

  document.getElementById('field15')?.addEventListener('change', selectState)
  document.getElementById('field23')?.addEventListener('change', selectIncorporationState)
  for (const id of ['field24', 'field25']) {
    document.getElementById(id)?.addEventListener('change', setIncorporationFieldValue)
  }
  document.getElementById('field26')?.addEventListener('input', setIncorporationFieldValue)

  updateFields()
  selectState()
  selectIncorporationState()
}

function updateFields() {
  const channelOn = document.querySelector('.js-partnership-channels:checked')
  const techOn = document.querySelector('.js-partnership-technology:checked')
  const techF = document.querySelectorAll('.technology-partnership-field')
  const techT = document.querySelectorAll('.technology-partnership-text')
  const chanF = document.querySelectorAll('.channel-partnership-field')
  const chanT = document.querySelectorAll('.channel-partnership-text')

  if (channelOn && !techOn) {
    localStorage.setItem('partnershipType', 'channel')
    toggleGroup(techF, 'none', true)
    toggleGroup(techT, 'none')
    toggleGroup(chanF, 'block', false, true)
    toggleGroup(chanT, 'inline-block')
  } else {
    localStorage.setItem('partnershipType', 'technology')
    toggleGroup(chanF, 'none', true)
    toggleGroup(chanT, 'none')
    toggleGroup(techF, 'block', false, true)
    toggleGroup(techT, 'inline-block')
  }
}

// helper to show/hide & (de)require inputs in a NodeList
// disable = true to disable & strip required;
// reenable = true to re-add required from data-required
function toggleGroup(nodes, display, disable = false, reenable = false) {
  for (const el of nodes) {
    el.style.display = display
    const inputs = el.querySelectorAll('input, select, textarea')
    for (const input of inputs) {
      if (disable && input.required) {
        input.removeAttribute('required')
        input.disabled = true
        input.setAttribute('data-required', 'pending')
      }
      if (reenable && input.getAttribute('data-required')) {
        input.setAttribute('required', 'required')
        input.disabled = false
        input.removeAttribute('data-required')
      }
    }
  }
}

function selectState() {
  const country = document.getElementById('field15')?.value
  const us = document.getElementById('usState')
  const ca = document.getElementById('caProv')
  const all = document.getElementById('allStateProv')
  const f16 = document.getElementById('field16')
  const f17 = document.getElementById('field17')
  const f18 = document.getElementById('field18')

  // ← if the user hasn’t picked a country yet, hide all three panels
  if (!country) {
    show(us, false)
    show(ca, false)
    show(all, false)
    return
  }

  if (country === 'US') {
    show(us, true)
    show(ca, false)
    show(all, false)
    f16.name = 'stateProv'
    f16.required = true
    f17.name = 'field17'
    f17.required = false
    f17.value = ''
    f18.name = 'field18'
    f18.required = false
    f18.value = ''
  } else if (country === 'CA') {
    show(ca, true)
    show(us, false)
    show(all, false)
    f17.name = 'stateProv'
    f17.required = true
    f16.name = 'field16'
    f16.required = false
    f16.value = ''
    f18.name = 'field18'
    f18.required = false
    f18.value = ''
  } else {
    show(all, true)
    show(us, false)
    show(ca, false)
    f18.name = 'stateProv'
    f18.required = true
    f16.name = 'field16'
    f16.required = false
    f16.value = ''
    f17.name = 'field17'
    f17.required = false
    f17.value = ''
  }
}

function selectIncorporationState() {
  const country = document.getElementById('field23')?.value
  const us2 = document.getElementById('usState2')
  const ca2 = document.getElementById('caProv2')
  const all2 = document.getElementById('allStateProv2')
  const f24 = document.getElementById('field24')
  const f25 = document.getElementById('field25')
  const f26 = document.getElementById('field26')

  // ← hide all until they pick something
  if (!country) {
    show(us2, false)
    show(ca2, false)
    show(all2, false)
    return
  }

  if (country === 'US') {
    show(us2, true)
    show(ca2, false)
    show(all2, false)
    f24.name = 'stateProv2'
    f24.required = true
    f25.value = ''
    f25.name = 'field25'
    f26.value = ''
    f26.name = 'field26'
  } else if (country === 'CA') {
    show(ca2, true)
    show(us2, false)
    show(all2, false)
    f25.name = 'stateProv2'
    f25.required = true
    f24.value = ''
    f24.name = 'field24'
    f26.value = ''
    f26.name = 'field26'
  } else {
    show(all2, true)
    show(us2, false)
    show(ca2, false)
    f26.name = 'stateProv2'
    f26.required = true
    f24.value = ''
    f24.name = 'field24'
    f25.value = ''
    f25.name = 'field25'
  }

  setIncorporationFieldValue()
}

function setIncorporationFieldValue() {
  const out = document.getElementById('incorporation_location')
  const a = document.getElementById('field24')
  const b = document.getElementById('field25')
  const c = document.getElementById('field26')
  const d = document.getElementById('field23')
  if (a && a.value) out.value = a.options[a.selectedIndex].text
  else if (b && b.value) out.value = b.options[b.selectedIndex].text
  else if (c && c.value) out.value = c.value
  else if (d && d.value) out.value = d.options[d.selectedIndex].text
}

// simple helper to show/hide
function show(el, yes) {
  if (!el) return
  if (yes) el.classList.remove('hide')
  else el.classList.add('hide')
}
